def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    result = []
    for i in range(num_cols):
        total = 0
        has_numeric = False
        for row in rows:
            if i < len(row):
                cell = row[i]
                if isinstance(cell, (int, float)):
                    total += cell
                    has_numeric = True
        if has_numeric:
            result.append(total)
        else:
            result.append("")
    return result

