from render import render_rows
from totals import column_totals


def export_csv(rows, totals=False):
    if totals:
        totals_row_data = column_totals(rows)
        # Build totals row with "TOTAL" as first cell
        row_with_total = ["TOTAL"] + totals_row_data
        # Render the totals row
        totals_rendered = render_rows([row_with_total])[0]
        # Render the main rows
        main_rendered = render_rows(rows)
        return "\n".join(main_rendered + [totals_rendered])
    else:
        return "\n".join(render_rows(rows))

